package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen2Test {



    @Test
    public void testFormData_SkipNonSubmittableAndDisabled() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);

        // Non-submittable element (e.g., a div)
        Element div = new Element(Tag.valueOf("div"), "", null);
        form.appendChild(div);

        // Submittable but disabled
        Element disabledInput = new Element(Tag.valueOf("input"), "", null);
        disabledInput.attr("name", "disabled_input");
        disabledInput.attr("disabled", "");
        form.appendChild(disabledInput);

        // Submittable but no name
        Element noNameInput = new Element(Tag.valueOf("input"), "", null);
        noNameInput.attr("type", "text");
        form.appendChild(noNameInput);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }












}

